import java.io.*
import java.util.*

class Solution {
    fun solve() {
        val n = readInt()
        val m = readInt()

        if (m == 1)
            write(n - 1)
        else
            write(1L * n * (m - 1))
    }

    companion object {
        private var reader: BufferedReader = BufferedReader(InputStreamReader(System.`in`))
        private var writer: PrintWriter = PrintWriter(System.out)
        private var currentLineTokens: ArrayDeque<String> = ArrayDeque()

        fun readAndSplitLine(): Array<String> {
            val line = reader.readLine() ?: ""
            return line.split(Regex("[\\s\\t]+")).filter { it.isNotEmpty() }.toTypedArray()
        }

        fun readToken(): String {
            while (currentLineTokens.isEmpty()) {
                currentLineTokens = ArrayDeque(readAndSplitLine())
            }
            return currentLineTokens.removeFirst()
        }

        fun readInt(): Int = readToken().toInt()
        fun readLong(): Long = readToken().toLong()
        fun readDouble(): Double = readToken().toDouble()
        fun readIntArray(): IntArray = readAndSplitLine().map { it.toInt() }.toIntArray()
        fun readLongArray(): LongArray = readAndSplitLine().map { it.toLong() }.toLongArray()
        fun readDoubleArray(): DoubleArray = readAndSplitLine().map { it.toDouble() }.toDoubleArray()

        fun readIntMatrix(numberOfRows: Int): Array<IntArray> {
            return Array(numberOfRows) { readIntArray() }
        }

        fun readAndTransposeIntMatrix(numberOfRows: Int): Array<IntArray> {
            val matrix = readIntMatrix(numberOfRows)
            val cols = matrix[0].size
            val ret = Array(cols) { IntArray(numberOfRows) }
            for (i in 0 until cols) {
                for (j in 0 until numberOfRows) {
                    ret[i][j] = matrix[j][i]
                }
            }
            return ret
        }

        fun readLines(quantity: Int): Array<String> {
            return Array(quantity) { (reader.readLine() ?: "").trim() }
        }

        fun <T> writeArray(array: Iterable<T>) {
            writer.println(array.joinToString(" "))
        }

        fun write(vararg array: Any?) {
            writeArray(array.toList())
        }

        fun <T> writeLines(array: Iterable<T>) {
            for (a in array) writer.println(a)
        }

        fun main() {
            try {
                Solution().solve()
            } catch (e: Exception) {
                throw e
            } finally {
                reader.close()
                writer.close()
            }
        }
    }
}

fun main() {
    Solution.main()
}
